/**
 * Exemplo CLÁSSICO (sem extensão): um projeto pronto montado SÓ com blocos
 * genéricos (HTML + CSS + Programação/Canvas), para a criança abrir, jogar e
 * editar "na mão". A IR não traz `extensions` (ou traz `[]`), então roda sem
 * nenhum facilitador instalado. Surgem na seção "Exemplos clássicos" do painel
 * de Extensões, carregados pelo mesmo caminho dos exemplos de extensão.
 */
export interface CoreExample {
  name: string
  experience: ExampleExperience
  description: string
  ir: SZIRV2
  /** Assets embutidos que o exemplo precisa (ex.: imagem de fundo por CSS). */
  assets?: ProjectAsset[]
}

